$ec_lang['lpn_lock_open_heading']='{name} има ову датотеку отворену.';
$ec_lang['lpn_lock_open_readonly']='Отвори само за читање';
// "Create a copy", not "my own copy" (Tom, 2026-08-04): two projects cannot share one name, and
